import { parseAddr } from './sheet.js'

// returns AST or null on grammar failure
export function parseFormula(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) { toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) { toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(src.slice(i)))) { toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  let p = 0
  const peekOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const fail = () => { throw FAIL }
  const FAIL = new Error('grammar')
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (peekOp('+') || peekOp('-')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (peekOp('*') || peekOp('/')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (peekOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (peekOp('-') || peekOp('+')) { const op = toks[p++].v; return { k: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const t = toks[p++]
    if (t.t === 'num') return { k: 'num', v: t.v }
    if (t.t === 'op') {
      if (t.v === '(') {
        const e = cmp()
        if (!peekOp(')')) fail()
        p++
        return { k: 'paren', e }
      }
      fail()
    }
    const up = t.v.toUpperCase()
    if (peekOp('(')) {
      p++
      const args = []
      if (peekOp(')')) { p++ } else {
        for (;;) {
          args.push(cmp())
          if (peekOp(',')) { p++; continue }
          if (peekOp(')')) { p++; break }
          fail()
        }
      }
      return { k: 'call', name: up, args }
    }
    if (peekOp(':')) {
      p++
      if (p >= toks.length || toks[p].t !== 'word') fail()
      const w2 = toks[p++].v
      return { k: 'range', a: t.v, b: w2 }
    }
    if (up === 'TRUE') return { k: 'bool', v: true }
    if (up === 'FALSE') return { k: 'bool', v: false }
    return { k: 'ref', w: t.v }
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e === FAIL) return null
    throw e
  }
}

export function hasMisplacedRange(n, argPos = false) {
  switch (n.k) {
    case 'range': return !argPos
    case 'bin': return hasMisplacedRange(n.l) || hasMisplacedRange(n.r)
    case 'un': return hasMisplacedRange(n.e)
    case 'paren': return hasMisplacedRange(n.e)
    case 'call': return n.args.some((a) => hasMisplacedRange(a, true))
    default: return false
  }
}

export function rangeCells(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push({ col: c, row: r })
  return out
}
