import { parseFormula, rangeCells } from './formula.js'
import { parseAddr, colName } from './sheet.js'

export function depsOf(cell) {
  if (cell.content[0] !== '=') return []
  const ast = parseFormula(cell.content.slice(1))
  if (!ast) return []
  const set = new Map()
  const add = (col, row) => set.set(col * 1000 + row, { col, row })
  const walk = (n) => {
    switch (n.k) {
      case 'ref': { const a = parseAddr(n.w); if (a) add(a.col, a.row); break }
      case 'range': { const cs = rangeCells(n); if (cs) cs.forEach((c) => add(c.col, c.row)); break }
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': case 'paren': walk(n.e); break
      case 'call': n.args.forEach(walk); break
    }
  }
  walk(ast)
  return [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row).map((c) => colName(c.col) + c.row)
}
EOF
