import { parseFormula, hasMisplacedRange, rangeCells } from './formula.js'
import { parseAddr, colName } from './sheet.js'

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ t: 'err', v: e })
const num = (v) => ({ t: 'num', v })
const NUM_RE = /^-?[0-9]+(\.[0-9]+)?$/

export function formatValue(v) {
  switch (v.t) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'err': return v.v
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function cmpCode(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const rank = { num: 0, text: 1, bool: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'num') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 'text') return cmpCode(a.v, b.v)
  return Number(a.v) - Number(b.v)
}

// number-or-error coercion for arithmetic positions
function toNum(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.v ? 1 : 0)
  if (v.t === 'text') return err('#VALUE!')
  return v
}
const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

export function evaluateAll(sheet) {
  const memo = new Map()
  const active = new Set()

  function cellValue(key) {
    if (memo.has(key)) return memo.get(key)
    const cell = sheet.map.get(key)
    if (!cell) return num(0)
    if (active.has(key)) return err('#CYCLE!')
    active.add(key)
    const v = evalContent(cell.content)
    active.delete(key)
    memo.set(key, v)
    return v
  }

  function evalContent(c) {
    if (c[0] === '=') {
      const ast = parseFormula(c.slice(1))
      if (!ast || hasMisplacedRange(ast)) return err('#ERR!')
      return ev(ast)
    }
    if (c === '') return num(0)
    if (NUM_RE.test(c)) return num(Number(c))
    if (ERRS.includes(c)) return err(c)
    return { t: 'text', v: c }
  }

  function refValue(w) {
    const a = parseAddr(w)
    return a ? cellValue(a.addr) : err('#REF!')
  }

  function expandArg(n) {
    if (n.k === 'range') {
      const cs = rangeCells(n)
      if (!cs) return [err('#REF!')]
      return cs.map((c) => cellValue(colName(c.col) + c.row))
    }
    return [ev(n)]
  }

  function ev(n) {
    switch (n.k) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'bool', v: n.v }
      case 'ref': return refValue(n.w)
      case 'range': return err('#ERR!')
      case 'paren': return ev(n.e)
      case 'un': {
        const x = toNum(ev(n.e))
        if (x.t === 'err') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': return bin(n)
      case 'call': return call(n)
    }
  }

  function bin(n) {
    const l = ev(n.l), r = ev(n.r)
    if (l.t === 'err') return l
    if (r.t === 'err') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const c = compare(l, r)
      const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
      return { t: 'bool', v: res }
    }
    const a = toNum(l), b = toNum(r)
    if (a.t === 'err') return a
    if (b.t === 'err') return b
    switch (n.op) {
      case '+': return fin(a.v + b.v)
      case '-': return fin(a.v - b.v)
      case '*': return fin(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
      case '^': return fin(Math.pow(a.v, b.v))
    }
  }

  function call(n) {
    const name = n.name, k = n.args.length
    if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) {
      if (k < 1) return err('#ERR!')
      const vals = n.args.flatMap(expandArg)
      const e = vals.find((v) => v.t === 'err')
      if (e) return e
      if (name === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
      const nums = []
      for (const v of vals) {
        const x = toNum(v)
        if (x.t === 'err') return x
        nums.push(x.v)
      }
      if (name === 'SUM') return fin(nums.reduce((s, x) => s + x, 0))
      if (name === 'AVG') return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
      if (name === 'MIN') return fin(Math.min(...nums))
      return fin(Math.max(...nums))
    }
    if (name === 'ABS') {
      if (k !== 1) return err('#ERR!')
      const vals = expandArg(n.args[0])
      const e = vals.find((v) => v.t === 'err')
      if (e) return e
      const x = toNum(vals[0])
      return x.t === 'err' ? x : num(Math.abs(x.v))
    }
    if (name === 'IF') {
      if (k !== 3) return err('#ERR!')
      const c = ev(n.args[0])
      if (c.t === 'err') return c
      if (c.t === 'text') return err('#VALUE!')
      const truth = c.t === 'bool' ? c.v : c.v !== 0
      return ev(n.args[truth ? 1 : 2])
    }
    return err('#NAME?')
  }

  const out = new Map()
  for (const c of sheet.cells) out.set(c.addr, cellValue(c.addr))
  return out
}
EOF
