export function colIndex(letters) {
  if (letters.length === 1) return letters.charCodeAt(0) - 64
  return 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
}
export function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26)) + String.fromCharCode(65 + (j % 26))
}
// returns {col,row,addr} or null
export function parseAddr(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  return { col: colIndex(letters), row, addr: letters + row }
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const seen = new Map()
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
    const a = parseAddr(m[1])
    if (!a) throw Object.assign(new Error(`error: line ${i + 1}: invalid cell address ${m[1].toUpperCase()}`), { sheetError: true })
    if (seen.has(a.addr)) throw Object.assign(new Error(`error: line ${i + 1}: cell ${a.addr} is declared twice`), { sheetError: true })
    seen.set(a.addr, { addr: a.addr, col: a.col, row: a.row, content: m[2] })
  })
  const cells = [...seen.values()].sort((x, y) => x.col - y.col || x.row - y.row)
  return { cells, map: seen }
}
