export function hasMisplacedRange(n, argPos = false) {
  switch (n.k) {
    case 'range': return !argPos
    case 'bin': return hasMisplacedRange(n.l) || hasMisplacedRange(n.r)
    case 'un': return hasMisplacedRange(n.e)
    case 'paren': return hasMisplacedRange(n.e)
    case 'call': return n.args.some((a) => hasMisplacedRange(a, true))
    default: return false
  }
}

export function rangeCells(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push({ col: c, row: r })
  return out
}
